package com.bank.qa.metrics;

import java.util.*;

// Computes the key performance metrics from recorded samples.
class MetricsCalculator {

    // Percentile over the FULL distribution (never average percentiles!).
    double percentile(List<Long> sortedMs, double pct) {
        if (sortedMs.isEmpty()) return 0;
        int idx = (int) Math.ceil(pct / 100.0 * sortedMs.size()) - 1;
        return sortedMs.get(Math.max(0, Math.min(idx, sortedMs.size() - 1)));
    }

    double average(List<Long> ms) {
        return ms.stream().mapToLong(Long::longValue).average().orElse(0);
    }

    double throughputPerSec(int completed, double windowSeconds) {
        return completed / windowSeconds;
    }

    double errorRatePct(int failed, int total) {
        return total == 0 ? 0 : 100.0 * failed / total;
    }
}
